mapper.sql:
select pt.id, pt.code, pt.source_id as sourceId, pt.source_code as sourceCode, pt.source_type as sourceType, pt.delivery_qty as deliveryQty, pt.warehouse_id as warehouseId, pt.warehouse_name as warehouseName, pt.create_user_name as createUserName, pt.create_time as createTime from packing_task pt where pt.is_deleted = FALSE
and ${params.sqlMap.default}
${params.permissionSql}
order by pt.create_time DESC

mapper.select:
SELECT packing_status as type, COUNT(*) AS count FROM ( SELECT pt.id, CASE WHEN EXISTS (SELECT 1 FROM wms_carton wc WHERE wc.packing_task_id = pt.id AND wc.is_deleted = FALSE AND wc.packing_status = 'completed') THEN 'packed' WHEN EXISTS (SELECT 1 FROM wms_carton wc WHERE wc.packing_task_id = pt.id AND wc.is_deleted = FALSE AND wc.packing_status IN ('completed', 'incomplete')) THEN 'packing' ELSE 'unpacked' END AS packing_status FROM packing_task pt
${permissionSql}
) AS subquery GROUP BY packing_status

SELECT pt.ID, CASE WHEN EXISTS ( SELECT 1 FROM wms_carton wc WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE AND wc.packing_status = 'completed' ) THEN 'packed' WHEN EXISTS ( SELECT 1 FROM wms_carton wc WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE AND wc.packing_status IN ( 'completed', 'incomplete' ) ) THEN 'packing' ELSE 'unpacked' END AS packing_status, CASE WHEN EXISTS ( SELECT 1 FROM wms_carton wc WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE AND wc.packing_status = 'success' ) THEN 'weighed' WHEN EXISTS ( SELECT 1 FROM wms_carton wc WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE AND (wc.packing_status IN ( 'success', 'unweighed' ) or wc.packing_status IN ( 'success', 'fail' )) ) THEN 'weighing' ELSE 'unweighted' END AS weightingStatus , (SELECT error_msg FROM wms_carton wc WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE order by wc.create_time DESC limit 1) as eroorMsg, (SELECT SUM(wcd.pack_qty) FROM wms_carton wc LEFT JOIN wms_carton_detail wcd ON wcd.main_id = wc.id and wcd.is_deleted = false WHERE wc.packing_task_id = pt.ID AND wc.is_deleted = FALSE) as packedQty, (SELECT SUM(package_weight) FROM wms_carton_spec wcs WHERE wcs.main_id = pt.ID AND wcs.is_deleted = FALSE) as packingWeight, (SELECT SUM(pd.picked_qty) FROM picking_lists pl LEFT JOIN picking_detail pd on pd.main_id = pl.id and pd.is_deleted = FALSE WHERE pl.source_id = pt.source_id AND pl.is_deleted = FALSE) as pickedQty FROM packing_task pt where pt.is_deleted = FALSE
AND pt.id IN
#{item}
